// The private keys of the key groups are never stored by the server: the
// keys generated by nexoctl are saved under the configuration directory
// (keys/<alias>/<key id>.pem, mode 0600), where dist sign-url finds them.

// safeFileName reports a name usable as a file name: 1 to 128 letters,
// digits, '.', '_' and '-', not "." nor "..".
func safeFileName(s string) bool {
	if s == "" || len(s) > 128 || s == "." || s == ".." {
		return false
	}
	for _, r := range s {
		ok := r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '.' || r == '_' || r == '-'
		if !ok {
			return false
		}
	}
	return true
}

// signingKeyPath returns the file of the private key keyID of alias.
func (e *env) signingKeyPath(alias, keyID string) (string, error) {
	if !safeFileName(keyID) || !safeFileName(alias) {
		return "", fmt.Errorf("%w: key id %q", domain.ErrInvalidArgument, keyID)
	}
	cfg, err := e.configPath()
	if err != nil {
		return "", err
	}
	return filepath.Join(filepath.Dir(cfg), "keys", alias, keyID+".pem"), nil
}

// savePrivateKey writes a generated private key: to out when set ("-":
// stdout), otherwise to the key store of the alias. It returns where the
// key went.
func (e *env) savePrivateKey(alias, keyID, pemData, out string) (string, error) {
	if out == "-" {
		if _, err := fmt.Fprint(e.deps.Stderr, pemData); err != nil {
			return "", err
		}
		return "-", nil
	}
	path := out
	if path == "" {
		var err error
		if path, err = e.signingKeyPath(alias, keyID); err != nil {
			return "", err
		}
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return "", err
	}
	if err := os.WriteFile(path, []byte(pemData), 0o600); err != nil {
		return "", err
	}
	return path, nil
}

// loadPrivateKey reads the stored private key keyID of alias; ok is false
// when there is none.
func (e *env) loadPrivateKey(alias, keyID string) (string, bool, error) {
	path, err := e.signingKeyPath(alias, keyID)
	if err != nil {
		return "", false, err
	}
	data, err := os.ReadFile(path) // #nosec G304 -- a file the user named on the command line
	if errors.Is(err, os.ErrNotExist) {
		return "", false, nil
	}
	if err != nil {
		return "", false, err
	}
	return string(data), true, nil
}

// keyGroupRecord is a key group.
type keyGroupRecord struct {
	Alias    string             `json:"alias"`
	KeyGroup nexoadmin.KeyGroup `json:"keyGroup"`
	// Key is the generated key, PrivateKeyFile where its private key was
	// saved ("-": printed on stderr).
	Key            *nexoadmin.PublicKey `json:"key,omitempty"`
	PrivateKeyFile string               `json:"privateKeyFile,omitempty"`
}

// keyRecord is a key of a key group.
type keyRecord struct {
	Alias          string `json:"alias"`
	KeyGroup       string `json:"keyGroup"`
	PrivateKeyFile string `json:"privateKeyFile,omitempty"`
	nexoadmin.PublicKey
}

func newDistKeyGroupCmd(e *env) *cobra.Command {
	cmd := groupCmd("keygroup", "Manage the key groups of the signed URLs and cookies")
	cmd.Long = `Manage the key groups whose keys sign the URLs and cookies of the signed
behaviors (--access signed --key-group ID). A group holds several keys, so that a
new key is added before the old one is removed. The private key of a key
generated by the server is returned once: nexoctl saves it under its
configuration directory (keys/ALIAS/KEYID.pem), where "dist sign-url" finds it,
or in --key-out.`
	key := groupCmd("key", "Add and remove the keys of a key group")
	key.AddCommand(newDistKeyAddCmd(e), newDistKeyRemoveCmd(e))
	cmd.AddCommand(newDistKeyGroupCreateCmd(e), newDistKeyGroupListCmd(e), newDistKeyGroupRemoveCmd(e), key)
	return cmd
}

func newDistKeyGroupCreateCmd(e *env) *cobra.Command {
	var (
		comment, algorithm, keyOut string
		bits                       int
		noKey                      bool
	)
	cmd := &cobra.Command{
		Use:               "create ALIAS ID [--no-key] [--algorithm ed25519|rsa] [--key-out FILE]",
		Short:             "Create a key group with a first key pair",
		Example:           "  nexoctl dist keygroup create local rilasci\n  nexoctl dist keygroup create local rilasci --algorithm rsa --bits 4096 --key-out rilasci.pem",
		Args:              exactArgs(2),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			alias, client, err := e.adminAlias(ctx, args[0])
			if err != nil {
				return err
			}
			in := nexoadmin.CreateKeyGroupRequest{ID: args[1], Comment: comment}
			if !noKey {
				in.GenerateKey = &nexoadmin.GenerateKeyRequest{Algorithm: algorithm, Bits: bits}
			}
			res, err := client.CreateKeyGroup(ctx, in)
			if err != nil {
				return fmt.Errorf("key group %q: %w", args[1], err)
			}
			rec := keyGroupRecord{Alias: alias, KeyGroup: res.KeyGroup}
			text := fmt.Sprintf("Created the key group `%s`.", res.KeyGroup.ID)
			if res.Key != nil {
				where, err := e.savePrivateKey(alias, res.Key.PublicKey.ID, res.Key.PrivateKeyPEM, keyOut)
				if err != nil {
					return fmt.Errorf("save the private key of %s (shown once by the server): %w", res.Key.PublicKey.ID, err)
				}
				rec.Key, rec.PrivateKeyFile = &res.Key.PublicKey, where
				text = fmt.Sprintf("Created the key group `%s` with the key %s (%s); private key saved to %s.",
					res.KeyGroup.ID, res.Key.PublicKey.ID, res.Key.PublicKey.Algorithm, where)
			}
			return e.out.Info(rec, text)
		},
	}
	f := cmd.Flags()
	f.StringVar(&comment, "comment", "", "free text")
	f.BoolVar(&noKey, "no-key", false, "create an empty group (add keys with \"dist keygroup key add\")")
	f.StringVar(&algorithm, "algorithm", "", "ed25519 (default) or rsa")
	f.IntVar(&bits, "bits", 0, "size of an RSA key (2048, 3072, 4096)")
	f.StringVar(&keyOut, "key-out", "", "file of the private key (\"-\": stderr; default: the key store of nexoctl)")
	return cmd
}

func newDistKeyGroupListCmd(e *env) *cobra.Command {
	return &cobra.Command{
		Use:               "list ALIAS",
		Aliases:           []string{"ls"},
		Short:             "List the key groups and their keys",
		Args:              exactArgs(1),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			alias, client, err := e.adminAlias(ctx, args[0])
			if err != nil {
				return err
			}
			groups, err := client.ListKeyGroups(ctx)
			if err != nil {
				return err
			}
			if len(groups) == 0 {
				return e.out.Note("No key group.")
			}
			for _, g := range groups {
				lines := []string{fmt.Sprintf("%s (%d %s)", g.ID, len(g.Keys), plural(len(g.Keys), "key", "keys"))}
				for _, k := range g.Keys {
					local := ""
					if _, ok, _ := e.loadPrivateKey(alias, k.ID); ok {
						local = " [private key stored]"
					}
					lines = append(lines, fmt.Sprintf("  %s %s %s%s", k.ID, k.Algorithm, cli.FormatTime(k.CreatedAt), local))
				}
				if err := e.out.Result(keyGroupRecord{Alias: alias, KeyGroup: g}, strings.Join(lines, "\n")); err != nil {
					return err
				}
			}
			return nil
		},
	}
}

func newDistKeyGroupRemoveCmd(e *env) *cobra.Command {
	return &cobra.Command{
		Use:               "remove ALIAS ID",
		Aliases:           []string{"rm"},
		Short:             "Remove a key group no distribution uses",
		Args:              exactArgs(2),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			alias, client, err := e.adminAlias(ctx, args[0])
			if err != nil {
				return err
			}
			if err := client.DeleteKeyGroup(ctx, args[1]); err != nil {
				return fmt.Errorf("key group %q: %w", args[1], err)
			}
			return e.out.Info(adminActionRecord{Alias: alias, Type: "keyGroup", Name: args[1], Action: "removed"}, fmt.Sprintf("Removed the key group `%s`.", args[1]))
		},
	}
}

func newDistKeyAddCmd(e *env) *cobra.Command {
	var (
		publicKey, algorithm, comment, keyOut string
		bits                                  int
	)
	cmd := &cobra.Command{
		Use:   "add ALIAS GROUP [--public-key FILE] [--algorithm ed25519|rsa] [--key-out FILE]",
		Short: "Add a key to a key group (generated, or your public key)",
		Example: `  nexoctl dist keygroup key add local rilasci
  nexoctl dist keygroup key add local rilasci --public-key mykey.pub.pem`,
		Args:              exactArgs(2),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			in := nexoadmin.AddKeyRequest{Algorithm: algorithm, Bits: bits, Comment: comment}
			if publicKey != "" {
				data, err := e.readDocument(publicKey)
				if err != nil {
					return err
				}
				in.PublicKeyPEM = string(data)
			}
			ctx := cmd.Context()
			alias, client, err := e.adminAlias(ctx, args[0])
			if err != nil {
				return err
			}
			res, err := client.AddKeyGroupKey(ctx, args[1], in)
			if err != nil {
				return fmt.Errorf("key group %q: %w", args[1], err)
			}
			rec := keyRecord{Alias: alias, KeyGroup: args[1], PublicKey: res.PublicKey}
			text := fmt.Sprintf("Added the key %s to `%s`.", res.PublicKey.ID, args[1])
			if res.PrivateKeyPEM != "" {
				where, err := e.savePrivateKey(alias, res.PublicKey.ID, res.PrivateKeyPEM, keyOut)
				if err != nil {
					return fmt.Errorf("save the private key of %s (shown once by the server): %w", res.PublicKey.ID, err)
				}
				rec.PrivateKeyFile = where
				text = fmt.Sprintf("Added the key %s (%s) to `%s`; private key saved to %s.", res.PublicKey.ID, res.PublicKey.Algorithm, args[1], where)
			}
			return e.out.Info(rec, text)
		},
	}
	f := cmd.Flags()
	f.StringVar(&publicKey, "public-key", "", "PEM public key (PKIX) to add instead of generating a key pair")
	f.StringVar(&algorithm, "algorithm", "", "ed25519 (default) or rsa")
	f.IntVar(&bits, "bits", 0, "size of an RSA key (2048, 3072, 4096)")
	f.StringVar(&comment, "comment", "", "free text")
	f.StringVar(&keyOut, "key-out", "", "file of the private key (\"-\": stderr; default: the key store of nexoctl)")
	return cmd
}

func newDistKeyRemoveCmd(e *env) *cobra.Command {
	return &cobra.Command{
		Use:               "remove ALIAS GROUP KEYID",
		Aliases:           []string{"rm"},
		Short:             "Remove a key from a key group (its signatures stop verifying)",
		Args:              exactArgs(3),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			alias, client, err := e.adminAlias(ctx, args[0])
			if err != nil {
				return err
			}
			if err := client.DeleteKeyGroupKey(ctx, args[1], args[2]); err != nil {
				return fmt.Errorf("key %s of %q: %w", args[2], args[1], err)
			}
			return e.out.Info(adminActionRecord{Alias: alias, Type: "key", Name: args[2], Action: "removed"},
				fmt.Sprintf("Removed the key %s from `%s`.", args[2], args[1]))
		},
	}
}

// signURLRecord is a signed URL or signed cookies.
type signURLRecord struct {
	Alias        string `json:"alias"`
	Distribution string `json:"distribution"`
	nexoadmin.SignedURL
}

// signingKeyOf finds the private key of a signature: --private-key, else
// the stored key --key-id, else the newest stored key of the key group of
// the behavior serving the URL.
func (e *env) signingKeyOf(ctx context.Context, client cli.AdminClient, alias, id, rawURL, scheme, host, keyFile, keyID string) (string, string, error) {
	if keyFile != "" {
		data, err := e.readDocument(keyFile)
		return string(data), keyID, err
	}
	if keyID != "" {
		pemData, ok, err := e.loadPrivateKey(alias, keyID)
		if err != nil {
			return "", "", err
		}
		if !ok {
			return "", "", cli.UsageError("no stored private key %s: give it with --private-key", keyID)
		}
		return pemData, keyID, nil
	}
	testURL := rawURL
	if strings.HasPrefix(testURL, "/") && (scheme != "" || host != "") {
		if scheme == "" {
			scheme = "https"
		}
		if host != "" {
			testURL = scheme + "://" + host + rawURL
		}
	}
	res, err := client.TestDistribution(ctx, id, nexoadmin.DistributionTestRequest{URL: testURL})
	if err != nil {
		return "", "", err
	}
	if res.Behavior.Signing == nil || res.Behavior.Access != nexoadmin.AccessSigned {
		return "", "", fmt.Errorf("%w: %s is served by a behavior with access %q: only the signed behaviors verify signatures",
			domain.ErrInvalidArgument, rawURL, res.Behavior.Access)
	}
	group, err := client.GetKeyGroup(ctx, res.Behavior.Signing.KeyGroup)
	if err != nil {
		return "", "", err
	}
	for i := len(group.Keys) - 1; i >= 0; i-- {
		pemData, ok, err := e.loadPrivateKey(alias, group.Keys[i].ID)
		if err != nil {
			return "", "", err
		}
		if ok {
			return pemData, group.Keys[i].ID, nil
		}
	}
	return "", "", cli.UsageError("no stored private key of the key group %q: give it with --private-key", group.ID)
}

func newDistSignURLCmd(e *env) *cobra.Command {
	var (
		expire, ip, keyID, keyFile, host, scheme, resource, notBefore string
		cookies                                                       bool
	)
	cmd := &cobra.Command{
		Use:   "sign-url ALIAS ID PATH|URL --expire DURATION [--ip CIDR] [--cookie]",
		Short: "Sign a URL (or cookies) of a signed behavior",
		Long: `Sign a URL of a signed behavior of the distribution (CloudFront-style
?Expires=&Signature=&Key-Pair-Id=, or ?Policy= for a custom policy with --ip,
--resource or --not-before), or the signed cookies of a resource (--cookie).
The private key is the one of --private-key, or the stored key of the key group
of the behavior (see "dist keygroup"). A path is completed with https (--scheme)
and the first exact domain (--host). Needs admin:SignDistributionURL.`,
		Example: `  nexoctl dist sign-url local website /downloads/v1.zip --expire 1h
  nexoctl dist sign-url local website /downloads/v1.zip --expire 1h --ip 1.2.3.4
  nexoctl dist sign-url local website /premium/ --expire 12h --cookie --resource 'https://www.example.com/premium/*'`,
		Args:              exactArgs(3),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			if expire == "" {
				return cli.UsageError("--expire is required (a duration: 1h, 7d)")
			}
			d, err := cli.ParseDuration(expire)
			if err != nil || d <= 0 {
				return cli.UsageError("invalid --expire %q: a positive duration (30m, 1h, 7d)", expire)
			}
			in := nexoadmin.SignRequest{URL: args[2], Scheme: scheme, Host: host, ExpiresIn: int64((d + time.Second - 1) / time.Second),
				IPRange: ip, Resource: resource, Cookies: cookies}
			if notBefore != "" {
				t, err := time.Parse(time.RFC3339, notBefore)
				if err != nil {
					return cli.UsageError("invalid --not-before %q: RFC 3339", notBefore)
				}
				in.NotBefore = &t
			}
			ctx := cmd.Context()
			alias, client, id, err := e.distAlias(ctx, args)
			if err != nil {
				return err
			}
			if in.PrivateKeyPEM, in.KeyPairID, err = e.signingKeyOf(ctx, client, alias, id, args[2], scheme, host, keyFile, keyID); err != nil {
				return fmt.Errorf("distribution %q: %w", id, err)
			}
			res, err := client.SignDistributionURL(ctx, id, in)
			if err != nil {
				return fmt.Errorf("distribution %q: %w", id, err)
			}
			rec := signURLRecord{Alias: alias, Distribution: id, SignedURL: *res}
			if !cookies {
				return e.out.Result(rec, res.URL)
			}
			lines := make([]string, 0, len(res.Cookies))
			for _, c := range res.Cookies {
				lines = append(lines, fmt.Sprintf("Set-Cookie: %s=%s; Expires=%s; Secure; HttpOnly", c.Name, c.Value, c.Expires.UTC().Format(time.RFC1123)))
			}
			return e.out.Result(rec, strings.Join(lines, "\n"))
		},
	}
	f := cmd.Flags()
	f.StringVar(&expire, "expire", "", "validity of the signature (30m, 1h, 7d)")
	f.StringVar(&ip, "ip", "", "only for the clients of this IP or CIDR")
	f.StringVar(&keyID, "key-id", "", "key pair id of the stored private key")
	f.StringVar(&keyFile, "private-key", "", "PEM private key file of a key of the key group")
	f.StringVar(&host, "host", "", "domain of the URL (default: the first exact domain)")
	f.StringVar(&scheme, "scheme", "", "scheme of the URL: https (default) or http")
	f.StringVar(&resource, "resource", "", "resource of a custom policy, with * and ? wildcards")
	f.StringVar(&notBefore, "not-before", "", "start of the validity (RFC 3339)")
	f.BoolVar(&cookies, "cookie", false, "sign cookies instead of the URL")
	return cmd
}

// certRecord is a certificate.
type certRecord struct {
	Alias string `json:"alias"`
	nexoadmin.Certificate
}

func newDistCertCmd(e *env) *cobra.Command {
	cmd := groupCmd("cert", "Manage the TLS certificates of the domains of the distributions")
	cmd.Long = `Manage the TLS certificates of the domains of the distributions (served by SNI on
every node): ACME (--auto: obtained and renewed by the leader), uploaded PEM
certificates (--cert --key), or none when a proxy terminates TLS (--none).
A wildcard alias needs the DNS-01 challenge: --auto --dns-provider NAME, a provider
of "nexoctl admin dns-provider".
Needs admin:ManageCertificates (and admin:ManageDistributions for "set").`
	cmd.AddCommand(newDistCertSetCmd(e), newDistCertListCmd(e), newDistCertRemoveCmd(e))
	return cmd
}

func newDistCertSetCmd(e *env) *cobra.Command {
	var (
		auto, none                bool
		certFile, keyFile, certID string
		challenge, dnsProvider    string
	)
	cmd := &cobra.Command{
		Use:   "set ALIAS ID (--auto [--challenge C] [--dns-provider NAME] | --none | --cert FILE --key FILE [--cert-id ID])",
		Short: "Set the TLS certificate of the domains of a distribution",
		Example: `  nexoctl dist cert set local website --auto
  nexoctl dist cert set local previews --auto --challenge dns-01 --dns-provider cf
  nexoctl dist cert set local website --cert crt.pem --key key.pem`,
		Args:              exactArgs(2),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			upload := certFile != "" || keyFile != ""
			n := 0
			for _, b := range []bool{auto, none, upload} {
				if b {
					n++
				}
			}
			if n != 1 {
				return cli.UsageError("give one of --auto, --none and --cert/--key")
			}
			if upload && (certFile == "" || keyFile == "") {
				return cli.UsageError("--cert and --key go together")
			}
			if dnsProvider != "" && challenge == "" {
				challenge = nexoadmin.ChallengeDNS01
			}
			if (challenge != "" || dnsProvider != "") && !auto {
				return cli.UsageError("--challenge and --dns-provider go with --auto")
			}
			switch challenge {
			case "", nexoadmin.ChallengeHTTP01, nexoadmin.ChallengeTLSALPN01:
				if dnsProvider != "" {
					return cli.UsageError("--dns-provider needs --challenge dns-01")
				}
			case nexoadmin.ChallengeDNS01:
				if dnsProvider == "" {
					return cli.UsageError("--challenge dns-01 needs --dns-provider")
				}
			default:
				return cli.UsageError("--challenge must be http-01, tls-alpn-01 or dns-01")
			}
			ctx := cmd.Context()
			alias, client, id, err := e.distAlias(ctx, args)
			if err != nil {
				return err
			}
			value := nexoadmin.CertificateAuto
			if none {
				value = nexoadmin.CertificateNone
			}
			var uploaded *nexoadmin.Certificate
			if upload {
				chain, err := os.ReadFile(certFile) // #nosec G304 -- a file the user named on the command line
				if err != nil {
					return err
				}
				key, err := os.ReadFile(keyFile) // #nosec G304 -- a file the user named on the command line
				if err != nil {
					return err
				}
				if certID == "" {
					certID = "dist-" + id
				}
				if uploaded, err = client.UploadCertificate(ctx, nexoadmin.UploadCertificateRequest{ID: certID, CertificatePEM: string(chain), PrivateKeyPEM: string(key)}); err != nil {
					return fmt.Errorf("certificate: %w", err)
				}
				value = nexoadmin.CertificateUploadPrefix + uploaded.ID
			}
			d, err := editDistribution(ctx, client, id, func(d *nexoadmin.Distribution) error {
				d.TLS = nexoadmin.DistributionTLS{Certificate: value, Challenge: challenge, DNSProvider: dnsProvider}
				return nil
			})
			if err != nil {
				return fmt.Errorf("distribution %q: %w", id, err)
			}
			text := fmt.Sprintf("TLS of `%s`: %s.", id, value)
			if dnsProvider != "" {
				text = fmt.Sprintf("TLS of `%s`: %s, challenge %s with the DNS provider %s.", id, value, challenge, dnsProvider)
			} else if challenge != "" {
				text = fmt.Sprintf("TLS of `%s`: %s, challenge %s.", id, value, challenge)
			}
			if uploaded != nil {
				text = fmt.Sprintf("Uploaded the certificate %s (%s, valid until %s); TLS of `%s`: %s.", uploaded.ID,
					strings.Join(uploaded.Domains, ", "), cli.FormatTime(uploaded.NotAfter), id, value)
			}
			return e.out.Info(distRecord{Alias: alias, Action: "certificate set", Distribution: *d}, text)
		},
	}
	f := cmd.Flags()
	f.BoolVar(&auto, "auto", false, "obtain and renew the certificate with ACME")
	f.BoolVar(&none, "none", false, "no certificate (TLS terminated by a proxy)")
	f.StringVar(&certFile, "cert", "", "PEM certificate chain (leaf first)")
	f.StringVar(&keyFile, "key", "", "PEM private key of the certificate")
	f.StringVar(&certID, "cert-id", "", "id of the uploaded certificate (default dist-ID)")
	f.StringVar(&challenge, "challenge", "", "ACME challenge with --auto: http-01, tls-alpn-01 or dns-01 (default: the one of the server)")
	f.StringVar(&dnsProvider, "dns-provider", "", "DNS provider of the dns-01 challenge (implies --challenge dns-01; required by a wildcard alias)")
	_ = cmd.RegisterFlagCompletionFunc("challenge", cobra.FixedCompletions(
		[]string{nexoadmin.ChallengeHTTP01, nexoadmin.ChallengeTLSALPN01, nexoadmin.ChallengeDNS01}, cobra.ShellCompDirectiveNoFileComp))
	_ = cmd.RegisterFlagCompletionFunc("dns-provider", completeAdminFlag(e, dnsProviderNames))
	return cmd
}

func newDistCertListCmd(e *env) *cobra.Command {
	return &cobra.Command{
		Use:               "list ALIAS",
		Aliases:           []string{"ls"},
		Short:             "List the certificates with their status and expiration",
		Args:              exactArgs(1),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			alias, client, err := e.adminAlias(ctx, args[0])
			if err != nil {
				return err
			}
			list, err := client.ListCertificates(ctx)
			if err != nil {
				return err
			}
			if len(list.Items) == 0 && len(list.ACME.Managed) == 0 {
				return e.out.Note("No certificate.")
			}
			if len(list.Items) > 0 {
				if err := e.out.Text(fmt.Sprintf("%-24s %-7s %-14s %-23s %-24s %s", "ID", "SOURCE", "STATUS", "EXPIRES", "DOMAINS", "USED BY")); err != nil {
					return err
				}
			}
			for _, c := range list.Items {
				status := fmt.Sprintf("%-14s", c.Status)
				switch c.Status {
				case nexoadmin.CertificateExpiring:
					status = e.out.Paint(cli.ColorYellow, status)
				case nexoadmin.CertificateExpired, nexoadmin.CertificateNotYetValid:
					status = e.out.Paint(cli.ColorRed, status)
				}
				text := strings.TrimRight(fmt.Sprintf("%-24s %-7s %s %-23s %-24s %s", c.ID, c.Source, status, cli.FormatTime(c.NotAfter),
					strings.Join(c.Domains, ","), orDash(strings.Join(c.UsedBy, ","))), " ")
				if c.LastError != "" {
					text += "\n  last renewal error: " + c.LastError
				}
				if err := e.out.Result(certRecord{Alias: alias, Certificate: c}, text); err != nil {
					return err
				}
			}
			for _, m := range list.ACME.Managed {
				if m.State == "issued" {
					continue
				}
				how := ""
				if m.DNSProvider != "" {
					how = fmt.Sprintf(", %s via %s", m.Challenge, m.DNSProvider)
				} else if m.Challenge != "" {
					how = ", " + m.Challenge
				}
				if err := e.out.Text(fmt.Sprintf("ACME %s pending for %s (distributions %s%s)", m.ID, strings.Join(m.Domains, ","),
					orDash(strings.Join(m.Distributions, ",")), how)); err != nil {
					return err
				}
			}
			return nil
		},
	}
}

func newDistCertRemoveCmd(e *env) *cobra.Command {
	return &cobra.Command{
		Use:               "remove ALIAS CERTID",
		Aliases:           []string{"rm"},
		Short:             "Remove a certificate no distribution names",
		Args:              exactArgs(2),
		ValidArgsFunction: completeAliasNames(e),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			alias, client, err := e.adminAlias(ctx, args[0])
			if err != nil {
				return err
			}
			if err := client.DeleteCertificate(ctx, args[1]); err != nil {
				return fmt.Errorf("certificate %q: %w", args[1], err)
			}
			return e.out.Info(adminActionRecord{Alias: alias, Type: "certificate", Name: args[1], Action: "removed"},
				fmt.Sprintf("Removed the certificate %s.", args[1]))
		},
	}
}
